"""Tree SHAP explains the same unrounded probability used to rank events."""
import time
from pathlib import Path
import joblib
import numpy as np
import pandas as pd
import shap
from ml.schema import FEATURES, NUMERIC, CATEGORICAL, prepare


def severity(probability):
    if probability >= .85:
        return 'Critical','P1'
    if probability >= .65:
        return 'High','P2'
    if probability >= .35:
        return 'Medium','P3'
    return 'Low','P4'

class Scorer:
    def __init__(self, model_path):
        # Load only the trusted model generated by train.py; never deserialize an uploaded file.
        self.bundle=joblib.load(Path(model_path))
        self.pre=self.bundle['preprocessor']
        self.model=self.bundle['model']
        self.explainer=shap.TreeExplainer(self.model,data=self.bundle['background'],
                                         feature_perturbation='interventional',model_output='probability')

    def score(self,frame,mapping=None):
        start=time.perf_counter()
        raw,x,ts,warnings=prepare(frame,mapping)
        encoded=self.pre.transform(x)
        probabilities=self.model.predict_proba(encoded)[:,1]
        encoder=self.pre.named_transformers_['cat'].named_steps['encode']
        for c,categories in zip(CATEGORICAL,encoder.categories_):
            unknown=set(x[c].dropna())-set(categories)
            if unknown:
                warnings.append(f'{c}: unseen category values encoded as unknown; predictions may be unreliable: '+', '.join(sorted(unknown)[:6]))
        elapsed=(time.perf_counter()-start)*1000
        return raw,x,ts,probabilities,warnings,elapsed

    def explain(self,values):
        x=pd.DataFrame([values]).reindex(columns=FEATURES)
        for c in NUMERIC:
            x[c]=pd.to_numeric(x[c],errors='coerce')
        for c in CATEGORICAL:
            x[c]=x[c].map(lambda v: np.nan if pd.isna(v) else v).astype(object)
        z=self.pre.transform(x)
        start=time.perf_counter()
        explanation=self.explainer(z,check_additivity=True)
        contributions=np.asarray(explanation.values)[0,:,1]
        base=float(np.asarray(explanation.base_values)[0,1])
        probability=float(self.model.predict_proba(z)[0,1])
        reconstructed=base+float(contributions.sum())
        if abs(reconstructed-probability)>1e-5:
            raise RuntimeError('SHAP additive check failed; explanation was not displayed.')
        grouped={f:0.0 for f in FEATURES}
        for group,value in zip(self.bundle['groups'],contributions):
            grouped[group]+=float(value)*100
        evidence=[]
        for f,total in grouped.items():
            missing=pd.isna(x.iloc[0][f])
            value=None if missing else x.iloc[0][f]
            if isinstance(value,np.generic):
                value=value.item()
            evidence.append({'feature':f,'value':value,'contribution_points':total,
                             'direction':'raises' if total>0 else 'lowers' if total<0 else 'neutral',
                             'imputed':bool(missing)})
        evidence.sort(key=lambda item:abs(item['contribution_points']),reverse=True)
        positive=[item for item in evidence if item['contribution_points']>.01 and not item['imputed']]
        descriptions={'duration':'connection duration (seconds)', 'src_bytes':'outgoing bytes', 'dst_bytes':'incoming bytes',
                      'src_packets':'outgoing packet count','dst_packets':'incoming packet count',
                      'failed_logins':'failed login count','unique_dst_ports':'distinct destination ports',
                      'protocol':'network protocol','service':'application service'}
        reason=('Observed values raising this model score: '+ '; '.join(
            f"{descriptions[item['feature']]} = {item['value']} (+{item['contribution_points']:.2f} points)" for item in positive[:3])+'.') if positive else 'No observed feature materially raises the model score relative to its background baseline.'
        return {'method':'Tree SHAP, interventional, probability space','base_score':base*100,'score':probability*100,
                'reconstructed_score':reconstructed*100,'additivity_error':abs(reconstructed-probability)*100,
                'features':evidence,'summary':reason,'latency_ms':(time.perf_counter()-start)*1000,
                'caveat':'Contributions explain the model, not a proven attack cause. Imputed features are assumptions, not observed evidence. Correlated features can share attribution.'}
